def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the contiguous template object.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append(comp)

    comp = max(components, key=len)
    r0, r1 = min(r for r, c in comp), max(r for r, c in comp)
    c0, c1 = min(c for r, c in comp), max(c for r, c in comp)
    template = [(r, c, grid[r][c]) for r, c in comp]

    # All same-colored isolated marks are placement points. Align the
    # template's distinctive anchor to each mark.
    colors = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in comp:
                colors.setdefault(grid[r][c], []).append((r, c))
    marker_color = max(colors, key=lambda k: len(colors[k]))
    targets = colors[marker_color]

    anchors = [(r, c) for r, c, v in template if v == 3]
    if anchors:
        ar, ac = anchors[0]
    else:
        # Template anchor is its central cell (the central 6 in the demo).
        ar, ac = min(template, key=lambda p: abs(p[0] - (r0+r1)/2) +
                                      abs(p[1] - (c0+c1)/2))[:2]

    for tr, tc in targets:
        for r, c, v in template:
            rr, cc = tr + r - ar, tc + c - ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
    return out
