def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Separate scattered marker cells from the compact template by finding
    # the densest small bounding box of non-background cells.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    best = None
    for r0 in range(h):
        for c0 in range(w):
            for rh in range(1, min(7, h-r0)+1):
                for cw in range(1, min(7, w-c0)+1):
                    p = [(r, c) for r, c in pts
                         if r0 <= r < r0+rh and c0 <= c < c0+cw]
                    if len(p) >= 5 and (best is None or len(p) > len(best)):
                        best = p

    r0, r1 = min(r for r,c in best), max(r for r,c in best)
    c0, c1 = min(c for r,c in best), max(c for r,c in best)
    stamp = [(r,c,grid[r][c]) for r,c in best]

    # Markers are isolated cells of the background-excluded color that
    # occur outside the template. In the first pattern they are 6s; in
    # the second pattern they are holes in the background.
    colors = {}
    for r,c in pts:
        if not (r0 <= r <= r1 and c0 <= c <= c1):
            colors.setdefault(grid[r][c], []).append((r,c))
    marker_color = max(colors, key=lambda v: len(colors[v]))
    targets = colors[marker_color]

    # Anchor is the template's 3 if it has one; otherwise its central cell.
    anchors = [(r,c) for r,c,v in stamp if v == 3]
    if anchors:
        ar, ac = anchors[0]
    else:
        ar, ac = min(((r,c) for r,c,v in stamp),
                     key=lambda p: abs(p[0]-(r0+r1)/2)+abs(p[1]-(c0+c1)/2))

    for tr,tc in targets:
        for r,c,v in stamp:
            rr,cc = tr+r-ar, tc+c-ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
    return out
